#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

typedef long long ll;
const ll MOD = 1e9+7;

ll mod_pow(ll base, int exp) {
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<ll>> p(6, vector<ll>(6, 1));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double val;
            cin >> val;
            p[i][j] = static_cast<ll>(round(val * mod_pow(100, MOD - 2))) % MOD;
        }
    for (int i = n; i < 6; ++i)
        for (int j = n; j < 6; ++j)
            p[i][j] = 1;

    vector<pair<int, int>> edges;
    for (int i = 0; i < 6; ++i)
        for (int j = 0; j < 3; ++j)
            edges.emplace_back(i, j);

    vector<ll> F(1 << 20, 0);
    vector<int> index_map(1 << 18, 0);
    int idx_counter = 0;

    for (int i = 0; i < 6; ++i)
        for (int j = i + 1; j < 6; ++j)
            for (int k = j + 1; k < 6; ++k) {
                vector<int> v = {i, j, k};
                do {
                    int msk1 = ((1 << (v[0] * 3)) ^ (1 << (v[1] * 3 + 1)) ^ (1 << (v[2] * 3 + 2)));
                    for (int mask = 0; mask < (1 << 18); ++mask)
                        if ((mask & msk1) == msk1)
                            index_map[mask] = idx_counter;
                } while (next_permutation(v.begin(), v.end()));
                ++idx_counter;
            }

    for (int mask = 0; mask < (1 << 18); ++mask) {
        ll prod = 1;
        for (int i = 0; i < 18; ++i) {
            if ((mask >> i) & 1)
                prod = (prod * p[edges[i].first][edges[i].second]) % MOD;
            else
                prod = (prod * (MOD + 1 - p[edges[i].first][edges[i].second])) % MOD;
        }
        F[index_map[mask]] = (F[index_map[mask]] + prod) % MOD;
    }

    for (int i = 0; i < 20; ++i)
        for (int mask = 0; mask < (1 << 20); ++mask)
            if (mask & (1 << i))
                F[mask] = (F[mask] + F[mask ^ (1 << i)]) % MOD;

    vector<pair<int, int>> edges2;
    for (int i = 0; i < 6; ++i)
        for (int j = 3; j < 6; ++j)
            edges2.emplace_back(i, j);

    ll total = 0;
    for (int mask = 0; mask < (1 << 18); ++mask) {
        ll prod = 1;
        for (int i = 0; i < 18; ++i) {
            if ((mask >> i) & 1)
                prod = (prod * p[edges2[i].first][edges2[i].second]) % MOD;
            else
                prod = (prod * (MOD + 1 - p[edges2[i].first][edges2[i].second])) % MOD;
        }
        ll val = (prod * ((1 - F[((1 << 20) - 1) ^ index_map[mask]] + MOD) % MOD)) % MOD;
        total = (total + val) % MOD;
    }

    cout << total << "\n";
    return 0;
}
